// ---------- cold open: epidemiecurve van blokjes (één blokje = één melding) ----------
const KOUD = { x0: 560, dx: 26, yb: 820, dagen: 32, bw: 18, bh: 9 };
const koudN = (d) => Math.round(Math.pow(2, d / 5.5));
